parts=['''<!doctype html><html lang="zh"><meta charset="utf-8"><title>Corner Reveal：候选规律归纳</title><style>body{font:16px/1.7 system-ui;max-width:1200px;margin:28px auto;padding:0 20px;color:#1b2937;background:#f4f6f8}section{padding:22px;background:white;margin:18px 0;border-radius:10px}table{border-collapse:collapse;width:100%}td,th{padding:8px;border:1px solid #ccd3da;text-align:left}img{max-width:100%}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}pre{white-space:pre-wrap}code{background:#edf0f3}summary{cursor:pointer}@media(max-width:700px){.pair{grid-template-columns:1fr}}</style><h1>Corner Reveal：从两个案例能归纳到哪一步？</h1><p>2026-10-29 · 离线分析 · 无物理执行、无正式策略修改</p>
<section><h2>结论</h2><p><b>得到一个可证伪的候选机制，尚未得到可靠的统一 Skill。</b>两例动作都大致沿可见衣形的横向向外牵拉，但抓取侧不同。该相关性可能意味着折叠结构的横向释放，也可能只是抬升、重力与落布造成的共同结果。</p><p>重新复查后，E153 降为 <b>UNCERTAIN</b>：操作前已有袖部边缘露出，不能确认目标袖口中点此前真正被覆盖。E353 的重新显露证据较强，但仍是 <b>PROVISIONAL</b>，不是人工确认成功。旧报告不覆盖，本页记录此次更严格判断。</p></section>
<section><h2>独立复查原图与真实动作</h2><p>沿用语义身份：正面领口在上时，图像左侧对应穿着者右袖口 RS。目标是袖口开口边缘中点，不是袖子的任意突出尖端。</p>''']
for c in data['cases']:
 eid=c['event_id'];source=ROOT/c['source'];a=c['actual_action'];parts.append(f'<h3>{eid} — {c["assessment"]}</h3><p>{h(c["source"])}</p><div class="pair">')
 for k in ['before','after']:
  b=base64.b64encode((source/k/'rgb.png').read_bytes()).decode();parts.append(f'<div>{k.upper()} 原始 RGB<img src="data:image/png;base64,{b}"></div>')
 parts.append('</div>')
